from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def lfu_ops(capacity: int, operations: list[str], arguments: list[list[int]]) -> list[int | None]:
    values: dict[int, int] = {}
    freq: dict[int, int] = {}
    buckets: dict[int, OrderedDict] = {}
    minimum = 0

    def touch(key: int) -> None:
        nonlocal minimum
        old = freq[key]
        buckets[old].pop(key)
        if not buckets[old] and minimum == old:
            minimum += 1
        freq[key] = old + 1
        buckets.setdefault(old + 1, OrderedDict())[key] = None

    out: list[int | None] = []
    for op, arg in zip(operations, arguments):
        if op == "get":
            key = arg[0]
            if key not in values:
                out.append(-1)
            else:
                touch(key)
                out.append(values[key])
        else:
            key, value = arg
            if capacity == 0:
                out.append(None)
                continue
            if key in values:
                values[key] = value
                touch(key)
            else:
                if len(values) >= capacity:
                    evict, _marker = buckets[minimum].popitem(last=False)
                    del values[evict]
                    del freq[evict]
                values[key] = value
                freq[key] = 1
                buckets.setdefault(1, OrderedDict())[key] = None
                minimum = 1
            out.append(None)
    return out

